notifications.sync:
function (doc, oldDoc, meta) {
  // Devices may not delete notifications. requireRole throws for an authenticated
  // device user and is a no-op during import, so this constrains devices only.
  if (doc._deleted) {
    requireRole("admin");
    return;
  }

  // Only the in-app channel reaches a device. The import filter already keeps
  // email/sms/push out, but channel membership is decided HERE, so this is the
  // enforcing copy: a provider notification that somehow got imported (an
  // on-demand admin GET, or an import predating this rule) is assigned no
  // channel and is therefore visible to nobody. Returning without calling
  // channel() is also what lets _resync retire documents imported earlier.
  if (doc.channel !== "cblite") {
    return;
  }

  // Route by the channel array the pipeline already writes (util.go syncChannel:
  // "tenant::{tenant}::user::{user_id}"). Deriving a channel name here instead
  // would duplicate that rule in a second place and let the two drift.
  if (!doc.sync_channels || !doc.user_id) {
    throw({forbidden: "notification requires sync_channels and user_id"});
  }
  channel(doc.sync_channels);
  access(doc.user_id, doc.sync_channels);

  // A device owns exactly one field: seen. Everything else belongs to the
  // pipeline, which rewrites these documents after every delivery attempt.
  // Compare field by field rather than stringifying the whole body, so top-level
  // key ordering cannot produce a false rejection.
  if (oldDoc && !oldDoc._deleted) {
    var k;
    for (k in doc) {
      if (k.charAt(0) === '_' || k === 'seen') continue;
      if (JSON.stringify(doc[k]) !== JSON.stringify(oldDoc[k])) { requireRole("admin"); return; }
    }
    for (k in oldDoc) {
      if (k.charAt(0) === '_' || k === 'seen') continue;
      if (!(k in doc)) { requireRole("admin"); return; }
    }
  }
}

notifications.import_filter:
function (doc) {
  // Only cblite notifications reach a device.
  //
  // One event fans out to several channels, and importing all of them meant a
  // single event arrived on the phone three times over, tagged email / sms /
  // push - one entry per provider the platform happened to use. Those three are
  // records of an outbound provider call, not things a user reads in the app.
  // cblite is the in-app channel, so exactly one document per event syncs.
  //
  // This also replaces the previous user allowlist. No user needs naming here
  // any more: send to anyone from the Send console and their cblite
  // notification syncs. And because the ~523M seeded documents are all
  // email / sms / push, none of them are imported.
  return doc.channel === "cblite";
}

devices.sync:
function (doc, oldDoc, meta) {
  if (doc._deleted) {
    requireRole("admin");
    return;
  }
  if (!doc.user_id || !doc.tenant_id) {
    throw({forbidden: "device requires tenant_id and user_id"});
  }
  // Only the authenticated user may register a device in their own name.
  requireUser(doc.user_id);

  // Separate channel from notifications, so the app's notification replicator
  // does not pull device registrations it has no use for.
  var ch = "tenant::" + doc.tenant_id + "::user::" + doc.user_id + "::devices";
  channel(ch);
  access(doc.user_id, ch);
}

devices.import_filter:
function (doc) {
  // Device registrations carry no channel. Import any document that looks like
  // a real registration; this skips Sync Gateway's own _sync:syncInfo, which
  // lives in this collection and has no user_id.
  return !!doc.user_id;
}
